SELECT COUNT(1)
FROM ticket_notification
WHERE event_id = #{eventId}

SELECT id, event_id, ticket_id, customer_user_id, content, created_at
FROM ticket_notification
WHERE event_id = #{eventId}

SELECT COUNT(1)
FROM ticket_notification
